      if (tileCtx) { tileCtx.clearRect(c[0] * T, c[1] * T, T, T); tileCtx.fillStyle = 'rgba(255,255,255,.08)'; tileCtx.fillRect(c[0] * T, c[1] * T, T, T); tileCtx.fillStyle = 'rgba(255,143,184,.35)'; tileCtx.fillRect(c[0] * T, c[1] * T, T, 1); }
