      ctx.fillStyle = 'rgba(255,230,200,.18)';
      for (var i = 0; i < 18; i++) { var wx = Math.floor(cam.x / 40) * 40 + i * 40 + (Math.sin(G.t + i) * 6); ctx.fillRect(wx, mh + 10 + (i % 4) * 14, 10, 1); }
