      ctx.fillStyle = 'rgba(255,255,255,.8)'; ctx.fillRect(g.x, g.y + g.h - h, 1, h);
      ctx.fillStyle = '#7A808A'; ctx.fillRect(g.x - 1, g.y + g.h - h, g.w + 2, 2);
