      ctx.fillStyle = '#3B4048';
      for (var d = (sgn > 0 ? e.off : 8 - e.off); d < len; d += 8) {
        var qx = e.ax + ux * d, qy = e.ay + uy * d;
        ctx.fillRect(Math.round(qx), Math.round(qy), 3, 2);
      }
      /* main courante */
