      ctx.fillStyle = '#2A2A33'; ctx.fillRect(l.x - 3, l.y0 - 3, 8, 4); ctx.fillRect(l.x - 3, l.y1 - 1, 8, 4);
      ctx.fillStyle = l.act ? '#FF3D7F' : l.warn && Math.floor(G.t * 14) % 2 ? '#FF9EC2' : '#6B6B78';
      ctx.fillRect(l.x - 1, l.y0 - 2, 4, 2); ctx.fillRect(l.x - 1, l.y1, 4, 2);
