      ctx.fillStyle = '#3B3E46'; ctx.fillRect(v.x + 1, v.y - 7, 10, 5); ctx.fillStyle = '#8FC3E8'; ctx.fillRect(v.x + 6, v.y - 7, 5, 5);
      ctx.fillStyle = hasPass() ? '#38D07A' : '#E3312D'; ctx.fillRect(v.x - 2, v.y - 6, 2, 2); ctx.fillRect(v.x + v.w, v.y - 6, 2, 2);
      ctx.fillStyle = 'rgba(120,180,255,.55)';
