      ctx.fillStyle = '#2F6BFF'; ctx.fillRect(v.x - gap, v.y + v.h / 2 - 1, v.w / 2, 2); ctx.fillRect(v.x + v.w / 2 + gap, v.y + v.h / 2 - 1, v.w / 2, 2);
      ctx.fillStyle = 'rgba(255,255,255,.8)'; ctx.fillRect(v.x - gap, v.y, 1, v.h); ctx.fillRect(v.x + v.w - 1 + gap, v.y, 1, v.h);
