    ctx.fillStyle = '#2A2A44'; ctx.fillRect(x + 2, y + 11, 2, 3 - lA); ctx.fillRect(x + 6, y + 11, 2, 2 + lA);
    ctx.fillStyle = '#FFFFFF'; ctx.fillRect(x + 1 + lA, y + 14 - lA, 3, 1); ctx.fillRect(x + 6 - lA, y + 13 + lA, 3, 1);
    ctx.fillStyle = '#FF5A8A'; ctx.fillRect(x + 1 + lA, y + 14 - lA, 1, 1); ctx.fillRect(x + 6 - lA, y + 13 + lA, 1, 1);
    /* sac à butin dans le dos */
    ctx.fillStyle = '#C9CED6'; ctx.fillRect(x - 2, y + 6, 3, 4); ctx.fillStyle = '#FFE45C'; ctx.fillRect(x - 1, y + 7, 1, 1);
    /* sweat violet, étoile Y2K */
    ctx.fillStyle = '#8E3BD9'; ctx.fillRect(x + 1, y + 6, 8, 5);
    ctx.fillStyle = '#B57BFF'; ctx.fillRect(x + 1, y + 6, 8, 1);
    ctx.fillStyle = '#FFE45C'; ctx.fillRect(x + 5, y + 7, 1, 3); ctx.fillRect(x + 4, y + 8, 3, 1);
    /* bras : tendu vers l'avant quand il bondit */
    ctx.fillStyle = '#8E3BD9';
    if (e.lunge > 0) ctx.fillRect(x + 9, y + 7, 3, 2); else ctx.fillRect(x + 8, y + 8 + run, 2, 2);
    ctx.fillStyle = '#F1C6A8'; if (e.lunge > 0) ctx.fillRect(x + 12, y + 7, 1, 2);
    /* tête : visage bien visible, fin masque de raton laveur sur les yeux, joues roses, sourire en coin */
    ctx.fillStyle = '#F1C6A8'; ctx.fillRect(x + 1, y, 9, 6);
    ctx.fillStyle = '#1D1D2B'; ctx.fillRect(x + 1, y + 2, 9, 2);
    var blink = Math.floor(G.t * 3 + e.x) % 9 === 0;
