      ctx.lineWidth = fs * 0.06; ctx.strokeStyle = c1; rr(ctx, -w / 2 + fs * 0.14, -h / 2 + fs * 0.14, w - fs * 0.28, h - fs * 0.28, h * 0.26); ctx.stroke();
      ctx.lineWidth = fs * 0.16; ctx.strokeStyle = '#FFFFFF'; ctx.strokeText(s.t, 0, fs * 0.04);
      ctx.fillStyle = c1; ctx.fillText(s.t, 0, fs * 0.04);
