    posters: function () { var out = []; for (var cx = 0; cx < L.w; cx += 28) { var gy = decorGround(cx); if (gy >= L.h * T) continue; var c = campaignAt(cx); var a = posterSlot(cx, gy, 60, c.selecta ? 80 : 26 + c.h, 20, 10); out.push([cx, !!c.selecta, a, gy]); } return out; },
    amb: function () { return { amb: amb.map(function (o) { return [o.k, Math.round(o.x / T), o.y, !!o.rat]; }), mice: mice.map(function (m) { return [m.hx, m.y, m.st]; }) }; },
